+// Uses NEON vectorization with an 8x8 micro-kernel for high performance on ARM.
 extern "C" void matmul(int n, const float* A, const float* B, float* C) {
+#if defined(__ARM_NEON)
+    constexpr int BM = 64; // Block size for rows
+    constexpr int BN = 64; // Block size for columns
+    constexpr int BK = 64; // Block size for k dimension
+    constexpr int MR = 8;  // Micro-kernel rows
+    constexpr int NR = 8;  // Micro-kernel cols
