+    std::fill(C, C + n * n, 0.0f);
+
+    for (int ii = 0; ii < n; ii += BM) {
+        int im_end = std::min(ii + BM, n);
+        for (int jj = 0; jj < n; jj += BN) {
+            int jm_end = std::min(jj + BN, n);
+            for (int kk = 0; kk < n; kk += BK) {
+                int km_end = std::min(kk + BK, n);
+
+                // Process 8x8 micro-tiles
+                for (int ir = ii; ir < im_end; ir += MR) {
+                    int ir_end = std::min(ir + MR, im_end);
+                    for (int jr = jj; jr < jm_end; jr += NR) {
+                        int jr_end = std::min(jr + NR, jm_end);
+                        
+                        // Initialize C accumulator registers
+                        float32x4_t c0_0 = vdupq_n_f32(0.0f);
+                        float32x4_t c1_0 = vdupq_n_f32(0.0f);
+                        float32x4_t c2_0 = vdupq_n_f32(0.0f);
+                        float32x4_t c3_0 = vdupq_n_f32(0.0f);
+                        float32x4_t c4_0 = vdupq_n_f32(0.0f);
+                        float32x4_t c5_0 = vdupq_n_f32(0.0f);
+                        float32x4_t c6_0 = vdupq_n_f32(0.0f);
+                        float32x4_t c7_0 = vdupq_n_f32(0.0f);
+                        
+                        float32x4_t c0_1 = vdupq_n_f32(0.0f);
+                        float32x4_t c1_1 = vdupq_n_f32(0.0f);
+                        float32x4_t c2_1 = vdupq_n_f32(0.0f);
+                        float32x4_t c3_1 = vdupq_n_f32(0.0f);
+                        float32x4_t c4_1 = vdupq_n_f32(0.0f);
+                        float32x4_t c5_1 = vdupq_n_f32(0.0f);
+                        float32x4_t c6_1 = vdupq_n_f32(0.0f);
+                        float32x4_t c7_1 = vdupq_n_f32(0.0f);
+
+                        // K-loop
+                        for (int k = kk; k < km_end; ++k) {
+                            // Load A column elements
+                            float32x4_t a0 = vld1q_lane_f32(A + (ir) * n + k, vdupq_n_f32(0), 0);
+                            float32x4_t a1 = vld1q_lane_f32(A + (ir+1) * n + k, vdupq_n_f32(0), 0);
+                            float32x4_t a2 = vld1q_lane_f32(A + (ir+2) * n + k, vdupq_n_f32(0), 0);
+                            float32x4_t a3 = vld1q_lane_f32(A + (ir+3) * n + k, vdupq_n_f32(0), 0);
+                            float32x4_t a4 = vld1q_lane_f32(A + (ir+4) * n + k, vdupq_n_f32(0), 0);
+                            float32x4_t a5 = vld1q_lane_f32(A + (ir+5) * n + k, vdupq_n_f32(0), 0);
+                            float32x4_t a6 = vld1q_lane_f32(A + (ir+6) * n + k, vdupq_n_f32(0), 0);
+                            float32x4_t a7 = vld1q_lane_f32(A + (ir+7) * n + k, vdupq_n_f32(0), 0);
+
+                            // Load B row elements (two sets of 4)
+                            float32x4_t b0_0 = vld1q_f32(B + k * n + jr);
+                            float32x4_t b1_0 = vld1q_f32(B + k * n + jr + 4);
+                            
+                            // FMA for first 4 cols
+                            c0_0 = vfmaq_f32(c0_0, b0_0, a0);
+                            c1_0 = vfmaq_f32(c1_0, b0_0, a1);
+                            c2_0 = vfmaq_f32(c2_0, b0_0, a2);
+                            c3_0 = vfmaq_f32(c3_0, b0_0, a3);
+                            c4_0 = vfmaq_f32(c4_0, b0_0, a4);
+                            c5_0 = vfmaq_f32(c5_0, b0_0, a5);
+                            c6_0 = vfmaq_f32(c6_0, b0_0, a6);
+                            c7_0 = vfmaq_f32(c7_0, b0_0, a7);
+                            
