+                            c1_1 = vfmaq_f32(c1_1, b1_0, a1);
+                            c2_1 = vfmaq_f32(c2_1, b1_0, a2);
+                            c3_1 = vfmaq_f32(c3_1, b1_0, a3);
+                            c4_1 = vfmaq_f32(c4_1, b1_0, a4);
+                            c5_1 = vfmaq_f32(c5_1, b1_0, a5);
+                            c6_1 = vfmaq_f32(c6_1, b1_0, a6);
+                            c7_1 = vfmaq_f32(c7_1, b1_0, a7);
+                        }
