+                            if (rows_to_store > 3) vst1q_f32(C + (ir+3) * n + jr, c3_0);
+                            if (rows_to_store > 4) vst1q_f32(C + (ir+4) * n + jr, c4_0);
+                            if (rows_to_store > 5) vst1q_f32(C + (ir+5) * n + jr, c5_0);
+                            if (rows_to_store > 6) vst1q_f32(C + (ir+6) * n + jr, c6_0);
+                            if (rows_to_store > 7) vst1q_f32(C + (ir+7) * n + jr, c7_0);
+                        }
+                        
+                        // Store next 4 cols
+                        if (cols_to_store >= 8) {
+                            if (rows_to_store > 0) vst1q_f32(C + (ir) * n + jr + 4, c0_1);
+                            if (rows_to_store > 1) vst1q_f32(C + (ir+1) * n + jr + 4, c1_1);
+                            if (rows_to_store > 2) vst1q_f32(C + (ir+2) * n + jr + 4, c2_1);
+                            if (rows_to_store > 3) vst1q_f32(C + (ir+3) * n + jr + 4, c3_1);
+                            if (rows_to_store > 4) vst1q_f32(C + (ir+4) * n + jr + 4, c4_1);
+                            if (rows_to_store > 5) vst1q_f32(C + (ir+5) * n + jr + 4, c5_1);
+                            if (rows_to_store > 6) vst1q_f32(C + (ir+6) * n + jr + 4, c6_1);
+                            if (rows_to_store > 7) vst1q_f32(C + (ir+7) * n + jr + 4, c7_1);
+                        }
+                    }
+                }
+            }
+        }
+    }
+    
+    // Handle any remaining tail elements if n is not a multiple of block sizes
+    // The above logic handles boundaries via min(), but we need to ensure correctness for all n
+    // Actually, the logic above is correct for any n because we use min() for boundaries.
+    // However, we must ensure that the inner loops don't go out of bounds.
+    // The current implementation assumes MR=8 and NR=8, but if ir+8 > im_end, we stop early.
+    // The store logic checks rows_to_store, so it's safe.
+#else
+    // Fallback for non-NEON: simple i-k-j order
+    std::fill(C, C + n * n, 0.0f);
     for (int i = 0; i < n; ++i)
