-            for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
-            C[i * n + j] = s;
+        for (int k = 0; k < n; ++k) {
+            float a = A[i * n + k];
+            for (int j = 0; j < n; ++j)
+                C[i * n + j] += a * B[k * n + j];
         }
+#endif
 }
